@admin.route('/userdata/', methods = ['GET', 'POST'])
@admin.route('/userdata', methods = ['GET', 'POST'])
def gambleradminuserdatapage():
	"""
	Shows userdata page.

	"""
	GamEditor = SelectGambler()
