@admin.route('/userdata/project/<titleid>/export', methods=['GET','POST']) 
def csv_table_export(titleid):
	"""
	Export health utilities from all patients for a given Gambler project
	
	:param titleid: The title of the Gambler folder/project
	:type: str
	:return: CSV file
	"""
	maincd = ConditionInfo()
	maincd.load(titleid)
	mainud = UserData()
	tabledata = UserInfo.select().where(UserInfo.titleid == titleid)
	v=0
	def generate():
		data = StringIO()
		w = csv.writer(data)
		# write header
		w.writerow(("uid","userid","titleid","firstname","lastname","age","hld","gender","race","finalconditionOrderOne","finalconditionOrderTwo","finalconditionOrderThree","finalconditionOrderFour","finalconditionOrderFive","finalconditionOrderSix","finalconditionOrderSeven","finalconditionOrderEight","finalconditionIntensityOne","finalconditionIntensityTwo","finalconditionIntensityThree","finalconditionIntensityFour","finalconditionIntensityFive","finalconditionIntensitySix","finalconditionIntensitySeven","finalconditionIntensityEight","finalconditionGambOne","finalconditionGambTwo","finalconditionGambThree","finalconditionGambFour","finalconditionGambFive","finalconditionGambSix","finalconditionGambSeven","finalconditionGambEight","finalconditionTimeTOne","finalconditionTimeTTwo","finalconditionTimeTThree","finalconditionTimeTFour","finalconditionTimeTFive","finalconditionTimeTSix","finalconditionTimeTSeven","finalconditionTimeTEight"))
		yield data.getvalue()
		data.seek(0)
		data.truncate(0)

		# write each log item
		for tableitr in tabledata.iterator():
			w.writerow((tableitr.uid,tableitr.userid,tableitr.titleid,tableitr.firstname,tableitr.lastname,tableitr.age,tableitr.hld,tableitr.gender,tableitr.race,tableitr.finalconditionOrderOne,tableitr.finalconditionOrderTwo,tableitr.finalconditionOrderThree,tableitr.finalconditionOrderFour,tableitr.finalconditionOrderFive,tableitr.finalconditionOrderSix,tableitr.finalconditionOrderSeven,tableitr.finalconditionOrderEight,tableitr.finalconditionIntensityOne,tableitr.finalconditionIntensityTwo,tableitr.finalconditionIntensityThree,tableitr.finalconditionIntensityFour,tableitr.finalconditionIntensityFive,tableitr.finalconditionIntensitySix,tableitr.finalconditionIntensitySeven,tableitr.finalconditionIntensityEight,tableitr.finalconditionGambOne,tableitr.finalconditionGambTwo,tableitr.finalconditionGambThree,tableitr.finalconditionGambFour,tableitr.finalconditionGambFive,tableitr.finalconditionGambSix,tableitr.finalconditionGambSeven,tableitr.finalconditionGambEight,tableitr.finalconditionTimeTOne,tableitr.finalconditionTimeTTwo,tableitr.finalconditionTimeTThree,tableitr.finalconditionTimeTFour,tableitr.finalconditionTimeTFive,tableitr.finalconditionTimeTSix,tableitr.finalconditionTimeTSeven,tableitr.finalconditionTimeTEight))
			yield data.getvalue()
			data.seek(0)
			data.truncate(0)
	# add a filename
	headers = Headers()
	headers.set('Content-Disposition', 'attachment', filename= str(titleid) + str("_export")+ '.csv')
	return Response(
        	stream_with_context(generate()),
        	mimetype='text/csv', headers=headers
    		)


@admin.route('/userdata/project/<titleid>/meta/export', methods=['GET','POST'])
def csv_meta_table_export(titleid):
	"""
	Export metadata from all patients for a given Gambler project
	
	:param titleid: The title of the Gambler folder/project
	:type: str
	:return: CSV file
	"""
	UMD = UserMetaData.select().where(UserMetaData.titleid == titleid)
	def generate():
		data = StringIO()
		w = csv.writer(data)
		# write header
		w.writerow(("entryid","userid","titleid","gambleid","currentPage","buttonPress","totalTime","conditionOneTime","conditionTwoTime","conditionThreeTime","conditionFourTime","conditionFiveTime","conditionSixTime","conditionSevenTime","conditionEightTime","conditionOneVideoTime","conditionTwoVideoTime","conditionThreeVideoTime","conditionFourVideoTime","conditionFiveVideoTime","conditionSixVideoTime","conditionSevenVideoTime","conditionEightVideoTime"))
		yield data.getvalue()
		data.seek(0)
		data.truncate(0)

		# write each log item
		for g in UMD.iterator():
			w.writerow((g.entryid,g.userid,g.titleid,g.gambleid,g.currentPage,g.buttonPress,g.totalTime,g.conditionOneTime,g.conditionTwoTime,g.conditionThreeTime,g.conditionFourTime,g.conditionFiveTime,g.conditionSixTime,g.conditionSevenTime,g.conditionEightTime,g.conditionOneVideoTime,g.conditionTwoVideoTime,g.conditionThreeVideoTime,g.conditionFourVideoTime,g.conditionFiveVideoTime,g.conditionSixVideoTime,g.conditionSevenVideoTime,g.conditionEightVideoTime))
			yield data.getvalue()
			data.seek(0)
			data.truncate(0)
	# add a filename
	headers = Headers()
	headers.set('Content-Disposition', 'attachment', filename= str(titleid) + '_metadata.csv')
	return Response(
        	stream_with_context(generate()),
        	mimetype='text/csv', headers=headers
    		)
