@admin.route('/languagesetup/<titleid>/edit/', methods = ['GET', 'POST'])
@admin.route('/languagesetup/<titleid>/edit', methods = ['GET', 'POST'])
def languageeditsetup(titleid):
	"""
	Page allows for langauge setup

	:return: URL 
	"""
	try:
		db.connect()
	except Exception as e:
		db.close()
		db.connect()
	Language_Setup = LanguageTranslation()
	LangTranslator = LangUserSystemTranslate().select(LangUserSystemTranslate,LangUserGenderRaceSystemTranslate,LangCode).join(LangUserGenderRaceSystemTranslate, on=(LangUserGenderRaceSystemTranslate.demographics_language ==LangUserSystemTranslate.language)).join(LangCode, on = (LangCode.language  == LangUserSystemTranslate.language)).where(LangUserSystemTranslate.language == titleid).get()
	db.close()
	Language_Setup.populate_obj(LangTranslator)
	if request.method == 'POST':
		Language_Setup.save(1)
		return redirect(url_for("admin.gamblersetupfinish"))
	elif request.method == 'GET':
		return render_template('language_setup.html', form = Language_Setup)	
