@admin.route('/languagesetup/', methods = ['GET', 'POST'])
@admin.route('/languagesetup', methods = ['GET', 'POST'])
def languagesetup():
	"""
	Page allows for langauge setup

	:return: URL 
	"""
	if (db.is_closed()==False):
		db.close()
	db.connect()
	LanguageEditor = SelectLanguage()
	LanguageEditor.languageselect.choices = [(c.language, c.language_name) for c in LangCode.select(LangCode.language, LangCode.language_name)]
	db.close()
	if request.method == "POST":
		if "Edit" in request.form:
			return redirect(url_for("admin.languageeditsetup",titleid=str(LanguageEditor.languageselect.data)))

		else:
			return redirect(url_for("admin.languagenewsetup"))

	elif request.method == "GET":
		return render_template("language_editor.html", form = LanguageEditor)
		
@admin.route('/advgamblersetup/', methods = ['GET', 'POST'])
@admin.route('/advgamblersetup', methods = ['GET', 'POST'])
def advGamblerEdit():
	"""
	Page allows for advance gambler project editing.

	:return: Downloaded project for export, and finished Gambler project URL link. 
	"""
	GamEditor = SelectGambler()
	if (db.is_closed()==False):
		db.close()
	db.connect()
	GambleLoader = GamblerInfo()
	GamblerList = GambleLoader.select(GamblerInfo.titleid, GamblerInfo.otitleid)
	choice = [(c.titleid, c.otitleid) for c in GamblerList]
	GamEditor.gamblertitle.choices = choice
	from playhouse.shortcuts import model_to_dict, dict_to_model
	if request.method == "POST":
		if 'Export' in request.form:
			GB_Object = GambleLoader.select().where(GamblerInfo.titleid == GamEditor.gamblertitle.data).get()
			json_data = json.dumps(model_to_dict(GB_Object))
			db.close()
		#	respone = Response(json_data,  mimetype='application/json')
		#	response.headers.set('Content-Disposition','attachment',filename=(GamEditor.gamblertitle.data + ".json"))
			x_attach = 'attachment;filename=' +  GamEditor.gamblertitle.data + '.json'
			return Response(json_data, mimetype='application/json',headers={'Content-Disposition':x_attach})
		elif "Upload" in request.form:
			f = request.files['filename']
			if  "json" in f.filename:
				GB_Object = GamblerInfo()
				GB_Object = dict_to_model(GamblerInfo, json.loads(request.files['filename'].read()))
				GB_Object.save()
				return redirect(url_for("admin.gamblersetupfinish"))
				
			else:
				return redirect(url_for("admin.languagenewsetup"))
	else:
		db.close()
		return render_template('advgamblersetup.html', form = GamEditor)
