@admin.route('/gamblersetup/', methods = ['GET', 'POST'])
@admin.route('/gamblersetup', methods = ['GET', 'POST'])
def gamblerformroute():
	"""
	Page allowing authors to 

	:return: URL to either Gambler setup or Gambler Edit page
	"""
	GamEditor = EditGambler()
	if (db.is_closed()==False):
		db.close()
	db.connect()
	session['prefil']=""
	GambleLoader = GamblerInfo()
	GamblerList = GambleLoader.select(GamblerInfo.titleid, GamblerInfo.otitleid)
	choice = [(c.titleid, c.otitleid) for c in GamblerList]
	GamEditor.gamblertitle.choices = choice
	GamEditor.prefil.choices = choice
	if "Edit" in request.form:
		if GamEditor.gamblertitle.data == None and GamEditor.gamblerid.data == None:
			flash('You must fill in at least one field are required, or press the New Gambler Project Button to start a new project')
			return render_template('gamblernewedit.html', form = GamEditor)
		else:
			if GamEditor.gamblertitle.data == None:
				return redirect(url_for("admin.gamblersetupeditform",titleid=str(GamEditor.gamblerid.data)))
			else:
				return redirect(url_for("admin.gamblersetupeditform",titleid=str(GamEditor.gamblertitle.data)))
	if "New" in request.form:
		return redirect(url_for("admin.gamblersetupform"))
	if "Prefil" in request.form:
		if GamEditor.prefil.data == None:
			return redirect(url_for("admin.gamblersetupform"))
		else:
			session['prefil']=GamEditor.prefil.data 
			return redirect(url_for("admin.gamblersetupform"))
	if "Delete" in request.form:
		GamSetup = GamblerSetup()
		rstatus = GamSetup.delete(str(GamEditor.gamblertitle.data))
		if rstatus != 1:
			shutil.rmtree(current_app.config['UPLOAD_FOLDER']+ str(rstatus),ignore_errors=True)
			return redirect(url_for("admin.gamblerformroute"))
	else:
		return render_template('gamblernewedit.html', form = GamEditor)

@admin.route('/gamblersetup/finish', methods = ['GET'])
def gamblersetupfinish():
	"""
	Finish page
	"""
	session.clear()
	return render_template('gamblersetupfinish.html', Title_Program = "Thank You", Status_Text = "If you would like to edit your project or create a new one, please return to the Setup page.")

