@admin.route('/gamblersetup/new/<titleid>/media', methods = ['GET', 'POST'])
def gamblersetupmediaform(titleid):
##This is where WTFforms must work from as it wants to be right as you're implemnting it.
#Globalize Upload Folder for path creation.
	"""
	Form for embedding Gambler Demographic videos

	:param titleid: The title of the Gambler folder/project
	:type: str
	:return: URL to Gambler setup Finish page 
	"""
	foldername = titleid
	VideoCreate1 = VideoCreate()
	maincd = ConditionInfo()
	ginfo = GamblerInfo.get(GamblerInfo.titleid == titleid)
	tid = ginfo.titleid
	maincd.load(tid)
	mechset = maincd.getmech(tid)
	setup = 0
	maincond2 = ConditionInfo()
	if session['prefil'] != "":
		maincond2.load(session['prefil'])
		mechset = maincond2.getmech(session['prefil'])
	mlhold = len(mechset)
	mhold = mechset[mlhold-1]
	if maincd.getmech(tid) is not None:
		for qq in maincd.getmech(tid):
			if int(qq) > 0:
				setup = int(qq)
